create table if not exists public.progression_games (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, description text not null, game_type text not null, reward_points integer not null default 0, difficulty text not null default 'easy', rules jsonb not null default '{}'::jsonb, enabled boolean not null default true, created_at timestamptz not null default now()); create table if not exists public.progression_challenges (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, description text not null, challenge_type text not null, target integer not null default 1, reward_points integer not null default 0, reward_badge_code text, period text not null default 'weekly', enabled boolean not null default true, created_at timestamptz not null default now()); create index if not exists progression_games_enabled_idx on public.progression_games(enabled); create index if not exists progression_challenges_enabled_idx on public.progression_challenges(enabled); insert into public.progression_games(code,name,description,game_type,reward_points,difficulty,rules) values ('daily_explorer','Daily Explorer','Discover a new location type today.','discovery',50,'easy','{"action":"location_diversity","target":1}'::jsonb),('cleanest_hunt','Cleanest Hunt','Check in at three verified locations.','checkin_streak',100,'medium','{"action":"check_in","target":3}'::jsonb),('verification_hero','Verification Hero','Help verify restroom availability.','verification',75,'easy','{"action":"verification","target":3}'::jsonb),('review_rally','Review Rally','Leave helpful reviews for the community.','reviews',100,'medium','{"action":"review","target":2}'::jsonb),('qr_quest','QR Quest','Scan a participating business QR experience.','qr',75,'easy','{"action":"qr_scan","target":1}'::jsonb),('route_runner','Route Runner','Complete a discovery route.','route',150,'hard','{"action":"route_complete","target":1}'::jsonb) on conflict(code) do update set name=excluded.name,description=excluded.description,reward_points=excluded.reward_points,rules=excluded.rules; insert into public.progression_challenges(code,name,description,challenge_type,target,reward_points,reward_badge_code,period) values ('three_checkins','Three Check-ins','Check in at three different locations.','check_in',3,75,null,'weekly'),('verify_five','Community Verifier','Verify five locations.','verification',5,125,null,'weekly'),('review_two','Helpful Reviewer','Write two reviews.','review',2,100,null,'weekly'),('new_types','Location Explorer','Visit three different location types.','location_diversity',3,150,'location_explorer','weekly'),('qr_scan_one','QR Scout','Scan one business QR experience.','qr_scan',1,75,null,'weekly'),('route_one','Route Finisher','Complete one route.','route_completion',1,150,null,'weekly'),('social_contributor','Community Contributor','Make three meaningful social contributions.','social_contribution',3,125,null,'weekly'),('favorite_five','Curator','Favorite five locations.','favorite',5,75,null,'weekly') on conflict(code) do update set name=excluded.name,description=excluded.description,target=excluded.target,reward_points=excluded.reward_points;
